const base = global.get('haBaseUrl') || 'http://127.0.0.1:8123';
const token = global.get('haToken') || '';
if (!token) {
    node.status({ fill: 'red', shape: 'ring', text: 'no HA token' });
    return null;
}
msg.url = base + '/api/states/sensor.solar_controller_solar';
msg.method = 'GET';
msg.headers = { Authorization: 'Bearer ' + token };
msg.entity = 'sensor.solar_controller_solar';
return msg;

if (!msg.payload || msg.payload.state === undefined) {
    node.status({ fill: 'red', shape: 'ring', text: 'bad response' });
    return null;
}
const st = msg.payload.state;
const u = msg.payload.attributes && msg.payload.attributes.unit_of_measurement
    ? msg.payload.attributes.unit_of_measurement : 'W';
node.status({ fill: 'green', shape: 'dot', text: st + ' ' + u });
msg.payload = { entity: msg.entity, state: st, unit: u };
return msg;

